import {describe, it, expect} from 'vitest';
import type {IncomingMessage, OutgoingMessage} from './messages.js';

describe('Message types', () => {
  it('ListSessionsMessage is part of IncomingMessage', () => {
    // @ts-expect-error - list_sessions is not yet in IncomingMessage
    const msg: IncomingMessage = {
      type: 'list_sessions',
      limit: 10,
      before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
    };
    expect(msg.type).toBe('list_sessions');
  });

  it('SessionListMessage is part of OutgoingMessage', () => {
    // @ts-expect-error - session_list is not yet in OutgoingMessage
    const msg: OutgoingMessage = {
      type: 'session_list',
      sessions: [
        {
          sessionId: 's1',
          createdAt: '2026-01-01T00:00:00.000Z',
          updatedAt: '2026-01-01T00:01:00.000Z',
          entryCount: 1,
        },
      ],
    };
    expect(msg.type).toBe('session_list');
  });
});

