function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const data: ListSessionsMessage = {type: 'list_sessions'};

  if ('limit' in message) {
    const limit = message.limit;
    if (typeof limit !== 'number' || !Number.isInteger(limit) || limit < 0 || limit > 200) {
      return {valid: false, error: 'list_sessions limit must be an integer between 0 and 200'};
    }
    data.limit = limit;
  }

  if ('before' in message) {
    const before = message.before;
    if (typeof before !== 'object' || before === null) {
      return {valid: false, error: 'list_sessions before must be a cursor object'};
    }
    const cursor = before as Record<string, unknown>;
    if (typeof cursor.sessionId !== 'string' || cursor.sessionId.length < 1 || cursor.sessionId.length > 128) {
      return {valid: false, error: 'list_sessions before sessionId must be a string between 1 and 128 chars'};
    }
    const updatedAt = cursor.updatedAt;
    const time =
      typeof updatedAt === 'string'
        ? Date.parse(updatedAt)
        : typeof updatedAt === 'number'
          ? updatedAt
          : Number.NaN;
    if (!Number.isFinite(time)) {
      return {valid: false, error: 'list_sessions before updatedAt must be a valid date'};
    }
    data.before = {sessionId: cursor.sessionId, updatedAt: cursor.updatedAt as string | number};
  }

  return {valid: true, data};
}

